import java.util.*;

public class Main {
    int[] nextGreaterElement(int[] nums1, int[] nums2) {
        Map<Integer, Integer> nextGreater = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>();                                   // a monotonic DECREASING stack of values still awaiting their answer
        for (int num : nums2) {
            while (!stack.isEmpty() && stack.peek() < num) {                            // num is the first bigger value for everything smaller on top
                nextGreater.put(stack.pop(), num);
            }
            stack.push(num);
        }
        int[] result = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            result[i] = nextGreater.getOrDefault(nums1[i], -1);                             // anything left on the stack at the end has no next greater (-1)
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums1 = {4, 1, 2};
        int[] nums2 = {1, 3, 4, 2};
        System.out.println(Arrays.toString(solution.nextGreaterElement(nums1, nums2)));
    }
}

