vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
    unordered_map<int, int> nextGreater;
    vector<int> stack;                                                                    // a monotonic DECREASING stack of values still awaiting their answer
    for (int num : nums2) {
        while (!stack.empty() && stack.back() < num) {                                        // num is the first bigger value for everything smaller on top
            nextGreater[stack.back()] = num;
            stack.pop_back();
        }
        stack.push_back(num);
    }
    vector<int> result;
